  'NÍVEL': { en: 'LEVEL', es: 'NIVEL' },
  'Cresça com previsibilidade.': { en: 'Grow with predictability.', es: 'Crezca con previsibilidad.' },
  'Adiciona algoritmos de prospecção, projeções financeiras e análises avançadas. Quando o SMART já não basta.': { en: 'Adds prospecting algorithms, financial projections and advanced analysis. For when SMART is no longer enough.', es: 'Agrega algoritmos de prospección, proyecciones financieras y análisis avanzados. Cuando SMART ya no alcanza.' },
