  'Alertas de churn · Curva A': { en: 'Churn alerts · A items', es: 'Alertas de churn · Curva A' },
  'Consultoria mensal dedicada': { en: 'Dedicated monthly consulting', es: 'Consultoría mensual dedicada' },
  'Alta Performance': { en: 'High performance', es: 'Alto rendimiento' },
  'Decisão diária 100% por dado.': { en: 'Daily decisions 100% on data.', es: 'Decisión diaria 100% por dato.' },
  'Gestão 360°. DRE automatizado, sugestão de compras via IA e previsibilidade orçamentária. Para o C-Level que decide todo dia.': { en: '360° management. Automated P&L, AI purchase suggestions and budget predictability. For the C-level that decides every day.', es: 'Gestión 360°. Estado de resultados automatizado, sugerencia de compras vía IA y previsibilidad presupuestaria. Para el C-level que decide todos los días.' },
  'DRE automatizado': { en: 'Automated P&L', es: 'Estado de resultados automatizado' },
