  'Deixe seus dados e a nossa equipe entra em contato.': { en: 'Leave your details and our team will get in touch.', es: 'Deje sus datos y nuestro equipo se pone en contacto.' },
  'Nome': { en: 'Name', es: 'Nombre' },
