  'Seus dados seguem a LGPD. Sem spam, sem vendedor insistente.': { en: 'Your data is handled under data protection law. No spam, no pushy sales rep.', es: 'Sus datos se tratan conforme a la ley de protección de datos. Sin spam, sin vendedor insistente.' },
  'Recebemos seus dados! Nossa equipe entra em contato em breve.': { en: 'We got your details. Our team will be in touch shortly.', es: '¡Recibimos sus datos! Nuestro equipo se pone en contacto en breve.' },
