  'Organização': { en: 'Organisation', es: 'Organización' },
  'Dados unificados e processos claros, a casa em ordem antes de crescer.': { en: 'Unified data and clear processes — the house in order before growing.', es: 'Datos unificados y procesos claros, la casa en orden antes de crecer.' },
