  'Resultado que se distribui: para a operação, o time e os clientes.': { en: 'Results that spread: to the operation, the team and the customers.', es: 'Resultado que se distribuye: a la operación, el equipo y los clientes.' },
  'Bons Processos': { en: 'Good processes', es: 'Buenos procesos' },
  'Decisão diária guiada por dado, não por achismo nem por planilha.': { en: 'Daily decisions guided by data, not by hunches or spreadsheets.', es: 'Decisión diaria guiada por datos, no por suposiciones ni por hojas de cálculo.' },
  'Como funciona': { en: 'How it works', es: 'Cómo funciona' },
  'Do dado ao reconhecimento.': { en: 'From the data to the recognition.', es: 'Del dato al reconocimiento.' },
  'Acompanhamento': { en: 'Monitoring', es: 'Seguimiento' },
  'Ao longo do ano, os indicadores de cada distribuidor são monitorados na plataforma SEWE.': { en: 'Throughout the year, each distributor metrics are monitored on the SEWE platform.', es: 'A lo largo del año, los indicadores de cada distribuidor son monitoreados en la plataforma SEWE.' },
  'Análise dos pilares': { en: 'Pillar analysis', es: 'Análisis de los pilares' },
