  'Portal de Vendas B2B2C': { en: 'B2B2C Sales Portal', es: 'Portal de Ventas B2B2C' },
  'Ecommerce Personalizado B2B': { en: 'Custom B2B Ecommerce', es: 'Ecommerce Personalizado B2B' },
  'Ecommerce B2C': { en: 'B2C Ecommerce', es: 'Ecommerce B2C' },
  'Força de Vendas e Gestão de Campo': { en: 'Sales Force and Field Management', es: 'Fuerza de Ventas y Gestión de Campo' },
  'CRM, Clientes e Atividades': { en: 'CRM, Customers and Activities', es: 'CRM, Clientes y Actividades' },
  'Alçada de Aprovações': { en: 'Approval Authority', es: 'Límites de Aprobación' },
  'Ecommerce Personalizado B2B: loja com carrinho e checkout modernos, para o cliente comprar sem depender de ninguém.': { en: 'Custom B2B Ecommerce: a store with a modern cart and checkout, so the customer buys without depending on anyone.', es: 'Ecommerce Personalizado B2B: tienda con carrito y checkout modernos, para que el cliente compre sin depender de nadie.' },
  'Ecommerce Personalizado B2B: loja com experiência moderna, carrinho e checkout, para o cliente comprar sem depender de ninguém.': { en: 'Custom B2B Ecommerce: a store with a modern experience, cart and checkout, so the customer buys without depending on anyone.', es: 'Ecommerce Personalizado B2B: tienda con experiencia moderna, carrito y checkout, para que el cliente compre sin depender de nadie.' },
  'Ecommerce B2C: sua loja para o consumidor final, no mesmo estoque e na mesma regra de preço da operação.': { en: 'B2C Ecommerce: your store for the end consumer, on the same inventory and pricing rules as the operation.', es: 'Ecommerce B2C: su tienda para el consumidor final, con el mismo inventario y la misma regla de precio de la operación.' },
  'Ecommerce B2C: sua loja para o consumidor final, no mesmo estoque e na mesma regra de preço do resto da operação.': { en: 'B2C Ecommerce: your store for the end consumer, on the same inventory and pricing rules as the rest of the operation.', es: 'Ecommerce B2C: su tienda para el consumidor final, con el mismo inventario y la misma regla de precio del resto de la operación.' },
  'Alçada de Aprovações: a exceção comercial sobe sozinha para quem pode decidir, com justificativa registrada e rastro de quem aprovou o quê.': { en: 'Approval Authority: the commercial exception escalates on its own to whoever can decide, with the justification recorded and a trail of who approved what.', es: 'Límites de Aprobación: la excepción comercial sube sola a quien puede decidir, con justificación registrada y rastro de quién aprobó qué.' },

  // Credencial Meta (provedor oficial) na seção de WhatsApp
  'Provedor oficial Meta': { en: 'Official Meta provider', es: 'Proveedor oficial Meta' },
  'Certificação da Meta para integrar a API do WhatsApp Business: número verificado, conversas dentro da política e sem risco de bloqueio.': { en: 'Meta certification to integrate the WhatsApp Business API: verified number, conversations within policy and no risk of a block.', es: 'Certificación de Meta para integrar la API de WhatsApp Business: número verificado, conversaciones dentro de la política y sin riesgo de bloqueo.' },
  'A SEWE é certificada oficialmente pela Meta para desenvolver e integrar soluções de automação e comunicação: confirmações, campanhas e atendimento pelo WhatsApp, com tudo registrado no CRM.': { en: 'SEWE is officially certified by Meta to develop and integrate automation and communication solutions: confirmations, campaigns and support over WhatsApp, all recorded in the CRM.', es: 'SEWE está certificada oficialmente por Meta para desarrollar e integrar soluciones de automatización y comunicación: confirmaciones, campañas y atención por WhatsApp, con todo registrado en el CRM.' },

